CREATE POLICY career_files_read_own ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'private-career-files' AND (storage.foldername(name))[1] = (select auth.uid())::text);
CREATE POLICY career_files_insert_own ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'private-career-files' AND (storage.foldername(name))[1] = (select auth.uid())::text);
CREATE POLICY career_files_update_own ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'private-career-files' AND (storage.foldername(name))[1] = (select auth.uid())::text) WITH CHECK (bucket_id = 'private-career-files' AND (storage.foldername(name))[1] = (select auth.uid())::text);
CREATE POLICY career_files_delete_own ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'private-career-files' AND (storage.foldername(name))[1] = (select auth.uid())::text);